import requests

URL = "https://ctl.example.com/api/v1/health"

try:
    # (connect timeout, read timeout) in seconds: never wait forever
    r = requests.get(URL, timeout=(3.05, 15))
    r.raise_for_status()
    print("OK", r.status_code, f"{r.elapsed.total_seconds():.2f}s")
except requests.exceptions.ProxyError as e:
    print("Proxy problem: check HTTPS_PROXY, NO_PROXY and proxy credentials:", e)
except requests.exceptions.SSLError as e:
    print("TLS problem: TLS-inspecting proxy, wrong CA bundle or clock skew:", e)
except requests.exceptions.ConnectTimeout:
    print("Connect timeout: packets dropped (firewall, route, VPN) or host down")
except requests.exceptions.ConnectionError as e:
    print("Connection failed: DNS failure or connection refused:", e)
except requests.exceptions.ReadTimeout:
    print("Connected, but the server was too slow: latency, load or a large response")
except requests.exceptions.HTTPError as e:
    print("Reached the server; it returned an HTTP error:", e.response.status_code)

